// Generated from the reviewed Meshy arm layers. The .back and .grip layers have the
// baked wooden haft removed (align-held-tools-upright work): the fist now grips the
// held tool's own (upright) handle instead of a painted haft. sourceSHA256 for those
// two layers is the post-edit byte hash. Embedded bytes ensure swift-run,
// packaged, and installed builds render the same trusted art.

import Foundation

enum FirstPersonArmLayer: String, CaseIterable, Hashable {
    case empty
    case back
    case grip
}

